from lesson_authoring import entry as E
B=[['拉丁 mora → morari','停顿、延迟 → 耽搁、停留']]
W=[
E('moratorium','英 /ˌmɒrəˈtɔːriəm/；美 /ˌmɔːrəˈtɔːriəm/','正式暂停；暂缓执行','给一项活动按下暂停键，先别继续，等条件或讨论有了结果再说。','来自晚期拉丁 moratorius 使延迟的之中性形式，底下是 morari 延迟。英语早期用于延期付款，后来扩大到正式暂停各种活动。',B+[['晚期拉丁 moratorius → 英语 moratorium','使延迟的 → 延期许可、正式暂停']],'a moratorium on construction 是暂停建设，不表示已经永远禁止建设。这个词常见于政策、机构决定或集体呼吁，比普通 break 更有正式宣布的意味。暂停多久、由谁决定，要看上下文，词本身不给出固定期限。','impose a moratorium on something 宣布暂停某事；lift a moratorium 解除暂停；a temporary moratorium。复数可用 moratoriums 或 moratoria。','ban 是禁止，moratorium 侧重暂缓。它也不是 memorandum 备忘录，虽然都是较长的正式词。',('The council announced a six-month moratorium on new construction in the area.','议会宣布暂停该地区的新建工程六个月。'),('Researchers called for a moratorium while the risks were reviewed.','研究人员呼吁在评估风险期间暂停相关活动。'),sources=['https://www.etymonline.com/word/moratorium','https://www.oxfordlearnersdictionaries.com/definition/english/moratorium']),
E('demur','英 /dɪˈmɜː/；美 /dɪˈmɜːr/','提出异议；表示不愿同意','事情正要往下走，有人说：等等，我对这点有意见。','经古法语 demorer 来自拉丁 demorari 停留、拖延。英语从迟疑、使事情停下来，经法律异议语境发展出表示反对。',B+[['拉丁 demorari → 古法语 demorer → 英语 demur','停留、延迟'],['英语后来的异议义','对提议有保留，不直接点头同意']],'demur 常写一种克制但明确的异议，不一定是大声争吵。without demur 表示没有提出异议、没有推辞。它偏正式，读评论、小说、会议报道比较常见。日常对话直接用 object 或 say no 往往更自然。','demur at a suggestion 对建议表示异议；agree without demur 毫无异议地同意。过去式 demurred，分词 demurring。','demur 是提出异议，demure 是文静、端庄，末尾多一个 e 就换了词性与意思。二者的历史联系也不能仅凭拼写认定。',('Most members agreed, but one demurred at the proposed deadline.','大多数成员同意了，但有一人对拟定的截止日期提出异议。'),('She accepted the extra responsibility without demur.','她没有推辞就承担了额外的责任。'),sources=['https://www.etymonline.com/word/demur','https://www.oxfordlearnersdictionaries.com/definition/english/demur']),
E('demure','英 /dɪˈmjʊə/；美 /dɪˈmjʊr/','文静的；端庄的；矜持的','表现得安静、收敛，不张扬；也可能是刻意做出这样的样子。','这个词的来源有不同解释，常联系古法语 meur 成熟、稳重，追到拉丁 maturus；也有 demorer 停留影响词形的分析。不能确定地拆成 de- + mor-。',[['古法语 meur 等可能来源','成熟、稳重；具体构成有争议'],['英语 demure','庄重、安静 → 端庄、矜持，也可指故作矜持']],'a demure smile 可以是含蓄的微笑，a demure dress 可以说衣着端庄、不张扬。它说的是外在表现，不等于这个人没有主见；有时上下文还暗示这种文静是装出来的。不要把它误看成 demur 的形容词。','a demure smile；a demure manner；a demure dress。','shy 是害羞，demure 是看上去文静、矜持，未必紧张怕人。demur 则是提出异议，两词只适合放在一起辨认，不能编成确定的同源直线。',('She gave a demure smile and let her colleague answer the question.','她含蓄地笑了笑，让同事回答那个问题。'),('The dress looked demure from the front but had a striking design at the back.','这条裙子正面看很端庄，背面的设计却很醒目。'),sources=['https://www.etymonline.com/word/demure','https://www.merriam-webster.com/dictionary/demure','https://www.oxfordlearnersdictionaries.com/definition/english/demure'])]
ROOT=dict(id='C0764',meaning='停顿；延迟；停留',core='MOR = DELAY / STAY',image='本来在前进的事情停了一下：可能是正式暂停，也可能因为有人提出异议。',intro='拉丁 mora 是停顿、延迟，morari 是停留、耽搁。moratorium 把它变成正式暂缓；demur 通过使程序停下的异议，走到今天的反对、推辞。拼写相近的 demure 另列作辨析，来源有争议，不把它冒充确定的直接后代。',forms='moratorium 经拉丁形容词形式进入；demur 经法语的停留、延迟动词进入。demure 不能机械拆出同一个 mor-，它还可能与成熟、稳重这一来源有关。',branches=[['正式暂缓','moratorium'],['提出异议，让事情先停一下','demur'],['易混词，来源另辨','demure']],contrasts='moratorium 暂停，demur 异议，demure 文静。三词的现代用途完全不同，尤其不要把 demure 当成 demur 加 e 的普通派生形式。',practice='A member may demur when a committee proposes lifting a moratorium.\n\n委员会提议解除暂停措施时，有成员可能提出异议。',words=[x['word'] for x in W],exclude={w:'专门法律、运输、生物或语言学词，或低频派生，先略过' for w in ['mora','remora','demurrer','demurrage','demurrable','demurral','remorate']})
